async function repairWorldbookEntryEjs(entry, originalEntry, config, onProgress = null) {
  const content = String(entry.content || '');
  const originalContent = originalEntry ? alignLocalVars(alignTags(String(originalEntry.content || ''))) : null;
  const local = repairWorldbookEjsWithCode(content, originalContent);
  if (local.inspection.valid) return local;
  if (!config.apiKey) return { ...local, error: 'Chưa sửa được bằng code. Hãy thiết lập API Key để AI sửa EJS.' };
  // Ship all EJS blocks (not arbitrary slices of a long template). Prose stays local.
  const payload = {
    task: 'repair_ejs_syntax', entry_name: entry.comment || entry.name || '', diagnostics: local.inspection.errors,
    blocks: local.inspection.blocks.map(b => ({ ejs_block_index: b.index, kind: b.kind, line: b.line, code: b.code, opening: b.opening, closing: b.closing })),
    original_blocks: originalContent == null ? null : inspectWorldbookEjs(originalContent).blocks.map(b => ({ ejs_block_index: b.index, kind: b.kind, code: b.code }))
  };
  const userPrompt = JSON.stringify(payload);
  if (userPrompt.length > 60000) return { ...local, error: 'Các khối EJS quá dài cho một lượt sửa an toàn. Hãy kiểm tra thủ công; bản dịch được giữ nguyên.' };
  if (!local.inspection.blocks.length) return { ...local, error: 'Chưa xác định được vùng EJS để sửa an toàn.' };
  try {
    if (onProgress) onProgress('Đang nhờ AI sửa EJS...');
    const raw = await callLlmChatCompletion(config, userPrompt, CW_EJS_REPAIR_SYSTEM_PROMPT, { taskType: 'ejs_syntax', taskName: 'Sửa EJS: ' + payload.entry_name, batchLabel: 'Toàn bộ EJS của entry' });
    const response = safeParseJsonAiObject(raw);
    if (response?.status !== 'repaired') throw new Error(response?.reason || 'AI chưa xác định được cách sửa EJS an toàn.');
    const fixed = applyWorldbookEjsPatches(content, response.changes);
    return { content: fixed, inspection: inspectWorldbookEjs(fixed), method: 'ai' };
  } catch (err) { return { ...local, error: String(err.message || err) }; }
}

function getTranslationEjsReport(data) {
  const entries = Array.isArray(data?.entries) ? data.entries : [];
  const items = entries.map((entry, index) => {
    const check = inspectWorldbookEjs(entry.content);
    return { index, name: entry.comment || entry.name || ('Mục WB #' + (index + 1)), hasEjs: check.hasEjs, valid: check.valid, errors: check.errors };
  });
  return { checkedAt: Date.now(), ejsCount: items.filter(i => i.hasEjs).length, failedCount: items.filter(i => !i.valid).length, items };
}

async function saveCheckedTranslation(id, data, syncToBridge = true) {
  // A completed transaction is required before refreshing the vault or reporting success.
  const db = await getTranslationsIdb();
  if (!db) throw new Error('Không mở được kho bản dịch. Hãy thử lại.');
  await new Promise((resolve, reject) => {
    const tx = db.transaction(CW_IDB_STORE, 'readwrite');
    tx.objectStore(CW_IDB_STORE).put({ id: String(id), data, savedAt: Date.now() });
    tx.oncomplete = resolve;
    tx.onerror = () => reject(new Error('Không lưu được kết quả EJS. Hãy thử lại.'));
    tx.onabort = tx.onerror;
  });
  window.__CW_ACTIVE_TRANSLATIONS__.set(String(id), data);
  if (syncToBridge) saveActiveTranslationsToStorage(true);
}

async function checkAllVaultEjs(overlay, button) {
  if (window.__CW_EJS_VAULT_BUSY__) return;
  window.__CW_EJS_VAULT_BUSY__ = true;
  const label = button.textContent;
  button.disabled = true;
  let savedAny = false;
  try {
    const records = await loadAllFromIndexedDb();
    let failed = 0;
    for (let i = 0; i < records.length; i++) {
      button.textContent = 'Kiểm tra EJS (' + (i + 1) + '/' + records.length + ')';
      const rec = records[i];
      const active = window.__CW_ACTIVE_TRANSLATIONS__?.get(String(rec.id));
      const data = structuredClone(active || rec.data);
      data.ejsReport = getTranslationEjsReport(data);
      if (data.ejsReport.failedCount) failed++;
      await saveCheckedTranslation(rec.id, data, false);
      savedAny = true;
      await new Promise(resolve => setTimeout(resolve, 0));
    }
    showToast('Đã kiểm tra ' + records.length + ' bản dịch; ' + failed + ' DLC có lỗi EJS.', failed ? 'warning' : 'success');
    await renderAiVaultTab(overlay);
  } catch (err) { showToast(String(err.message || err), 'error'); }
  finally {
    if (savedAny) saveActiveTranslationsToStorage(true);
    button.disabled = false; button.textContent = label; window.__CW_EJS_VAULT_BUSY__ = false;
  }
}

function findOriginalEjsEntry(entry, index, originals) {
  if (!Array.isArray(originals)) return null;
  const key = entry.entryKey || entry.__cwEntryKey;
  if (key) return originals.find(e => (e.entryKey || e.__cwEntryKey) === key) || null;
  if (entry.uid != null) return originals.find(e => e.uid != null && String(e.uid) === String(entry.uid)) || null;
  // Index-only sources have no stronger identity; use position only in the same version.
  return originals[index] || null;
}

async function repairVaultTranslationEjs(record, overlay, button) {
  if (window.__CW_EJS_VAULT_BUSY__) return;
  window.__CW_EJS_VAULT_BUSY__ = true;
  const label = button.textContent;
  button.disabled = true;
  try {
    const freshRecord = (await loadAllFromIndexedDb()).find(rec => String(rec.id) === String(record.id));
    if (!freshRecord) throw new Error('Bản dịch này đã được xóa. Hãy tải lại danh sách.');
    const storedSnapshot = JSON.stringify(freshRecord.data);
    const active = window.__CW_ACTIVE_TRANSLATIONS__?.get(String(record.id));
    const data = structuredClone(active || freshRecord.data);
    let source = window.__CW_ORIGINAL_PROJECT_DATA__?.get(String(record.id));
    if (!source) {
      try { source = await fetchProjectEntries(record.id, { forceRefresh: true }); } catch (_) {}
    }
    const originals = source?.project?.version === data.project?.version ? source.entries : null;
    const config = getAiTranslationConfig();
    let fixedCount = 0;
    const failures = [];
    for (let i = 0; i < (data.entries || []).length; i++) {
      const entry = data.entries[i];
      if (inspectWorldbookEjs(entry.content).valid) continue;
      button.textContent = 'Sửa EJS (' + (i + 1) + '/' + data.entries.length + ')';
      const result = await repairWorldbookEntryEjs(entry, findOriginalEjsEntry(entry, i, originals), config);
      if (result.inspection.valid) { entry.content = result.content; fixedCount++; }
      else failures.push({ name: entry.comment || entry.name || ('Mục WB #' + (i + 1)), error: result.error || 'Chưa sửa được EJS.' });
    }
    data.ejsReport = getTranslationEjsReport(data);
    const latest = (await loadAllFromIndexedDb()).find(rec => String(rec.id) === String(record.id));
    if (!latest || JSON.stringify(latest.data) !== storedSnapshot || window.__CW_ACTIVE_TRANSLATIONS__?.get(String(record.id)) !== active) {
      throw new Error('Bản dịch đã thay đổi trong lúc sửa EJS. Hãy tải lại danh sách và thử lại để giữ chỉnh sửa mới.');
    }
    await saveCheckedTranslation(record.id, data);
    showToast('Đã sửa ' + fixedCount + ' mục; còn ' + data.ejsReport.failedCount + ' mục lỗi EJS. Cài lại DLC để áp dụng vào Worldbook.', data.ejsReport.failedCount ? 'warning' : 'success');
    if (failures.length) openModal('<pre style="white-space:pre-wrap">' + escapeHtml(failures.map(f => f.name + ': ' + f.error).join('\n\n')) + '</pre>', 'Các mục EJS chưa sửa được');
    await renderAiVaultTab(overlay);
  } catch (err) { showToast(String(err.message || err), 'error'); }
  finally { button.disabled = false; button.textContent = label; window.__CW_EJS_VAULT_BUSY__ = false; }
}
