    "  const toolbarHtml = `<div class=\"admin-review-toolbar\"><label class=\"admin-review-sort-control\"><span>排序</span><select data-admin-review-sort><option value=\"oldest\" ${sort === 'oldest' ? 'selected' : ''}>最旧优先</option><option value=\"latest\" ${sort === 'latest' ? 'selected' : ''}>最新优先</option></select></label><div class=\"admin-review-type-filters\">${typeOptions.map(type => `<button type=\"button\" class=\"admin-review-filter-btn ${type === projectType ? 'active' : ''}\" data-admin-review-type=\"${escapeHtml(type)}\">${escapeHtml(type || '全部')}</button>`).join('')}</div></div>`;",
