function getTranslatedTagLabel(tag, projectId = null) {
  if (!tag) return '';
  const cleanTag = String(tag).trim();
  if (!cleanTag) return '';
  if (projectId && typeof window !== 'undefined' && window.__CW_TRANSLATED_TITLES__) {
    const projectTrans = window.__CW_TRANSLATED_TITLES__.get(projectId);
    if (projectTrans?.tags && typeof projectTrans.tags === 'object' && projectTrans.tags[cleanTag]) {
      return projectTrans.tags[cleanTag];
    }
  }
  if (typeof window !== 'undefined' && window.__CW_TRANSLATED_TAGS__?.has(cleanTag)) {
    return window.__CW_TRANSLATED_TAGS__.get(cleanTag);
  }
  if (typeof window !== 'undefined' && window.__CW_TRANSLATED_TITLES__) {
    for (const item of window.__CW_TRANSLATED_TITLES__.values()) {
      if (item?.tags && typeof item.tags === 'object' && item.tags[cleanTag]) {
        if (window.__CW_TRANSLATED_TAGS__) window.__CW_TRANSLATED_TAGS__.set(cleanTag, item.tags[cleanTag]);
        return item.tags[cleanTag];
      }
    }
  }
  return FACET_TAG_TRANSLATIONS[cleanTag] || cleanTag;
}

function stripAccents(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, m => m === 'đ' ? 'd' : 'D')
    .toLowerCase();
}

